// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContentNewsSource) predicate.ContentNewsSource {
	return predicate.ContentNewsSource(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContentNewsSource) predicate.ContentNewsSource {
	return predicate.ContentNewsSource(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContentNewsSource) predicate.ContentNewsSource {
	return predicate.ContentNewsSource(sql.NotPredicates(p))
}
